package com.autocare.platform.order;
import java.time.Instant;import java.util.*;import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.security.oauth2.jwt.*;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.servlet.MockMvc;
import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties="JWT_SECRET=test-only-secret-with-at-least-32-characters") @AutoConfigureMockMvc
class CommissionHttpTest {
 @Autowired MockMvc mvc;@MockitoBean CommissionLedger ledger;@MockitoBean JwtDecoder decoder;
 @BeforeEach void tokens(){when(decoder.decode(anyString())).thenAnswer(c->{String t=c.getArgument(0);return Jwt.withTokenValue(t).header("alg","HS256").subject("1").claim("subject_type",t.equals("owner")?"user":"staff_account").claim("role",t.equals("manager")?"MERCHANT":t.equals("owner")?"OWNER":t.equals("staff")?"STAFF":"TECHNICIAN").claim("app_id","merchant-account").claim("merchant_id",1).claim("jti","test").expiresAt(Instant.now().plusSeconds(600)).build();});}
 @Test void anonymousOwnerStaffAndTechCannotViewMoney()throws Exception{mvc.perform(get("/api/merchant/commissions")).andExpect(status().isUnauthorized());for(String t:List.of("owner","staff","tech"))mvc.perform(get("/api/merchant/commissions").header("Authorization","Bearer "+t)).andExpect(status().isForbidden());verifyNoInteractions(ledger);}
 @Test void strictPaginationRejectsUnknownDuplicateAndHugeInputs()throws Exception{for(String query:List.of("merchant_id=2","amount=0.01","page=0","page=-1","page=1000001","page=1&page=2","page_size=51","page_size=0","page=","page=1.5"))mvc.perform(get("/api/merchant/commissions?"+query).header("Authorization","Bearer manager")).andExpect(status().isBadRequest());verifyNoInteractions(ledger);}
 @Test void managerReadIsScopedNoStoreAndNoWriteRoute()throws Exception{when(ledger.list(any(),eq(1),eq(20))).thenReturn(Map.of("merchant_id",1));mvc.perform(get("/api/merchant/commissions").header("Authorization","Bearer manager")).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.data.merchant_id").value(1));var actor=org.mockito.ArgumentCaptor.forClass(com.autocare.platform.service.MerchantActor.class);verify(ledger).list(actor.capture(),eq(1),eq(20));org.junit.jupiter.api.Assertions.assertEquals(1,actor.getValue().merchantId());mvc.perform(post("/api/merchant/commissions").header("Authorization","Bearer manager").contentType("application/json").content("{}")).andExpect(status().isMethodNotAllowed());}
 @Test void databaseErrorsNeverLeakSql()throws Exception{when(ledger.list(any(),anyInt(),anyInt())).thenThrow(new org.springframework.dao.DataAccessResourceFailureException("private SQL"));mvc.perform(get("/api/merchant/commissions").header("Authorization","Bearer manager")).andExpect(status().isServiceUnavailable()).andExpect(jsonPath("$.message").value("佣金账单暂不可用，请稍后重试"));}
}
